// src/math/growth.ts
function cagr(startValue, endValue, years) {
  return Math.pow(endValue / startValue, 1 / years) - 1;
}
function compoundGrowth(startValue, rate, years) {
  return startValue * Math.pow(1 + rate, years);
}
function reversionValue(exitNoi, exitCapRate) {
  return exitNoi / exitCapRate;
}
function operatingExpenseRatio(opex, egi2) {
  return opex / egi2;
}
function noiFromOer(egi2, opexRatio) {
  return egi2 * (1 - opexRatio);
}
function perUnit(total, units) {
  return total / units;
}

