// src/quiz/templates/dscrSensitivityRate.ts
function buildSolution12(noi2, loan, oldRate, newRate, amortYears) {
  const oldDs = annualDebtService(loan, oldRate, amortYears);
  const newDs = annualDebtService(loan, newRate, amortYears);
  const oldDscr = dscr(noi2, oldDs);
  const newDscr = dscr(noi2, newDs);
  const delta = newDscr - oldDscr;
  return {
    formula: "DS at rate r = loan \xD7 loanConstant(r, n);  DSCR = NOI / DS",
    steps: [
      {
        label: "DS @ old rate",
        expression: `${formatUsd(loan)} @ ${formatPct(oldRate)} / ${formatYears(amortYears)}`,
        result: formatUsd(oldDs)
      },
      {
        label: "DSCR @ old rate",
        expression: `${formatUsd(noi2)} / ${formatUsd(oldDs)}`,
        result: formatMultiple(oldDscr)
      },
      {
        label: "DS @ new rate",
        expression: `${formatUsd(loan)} @ ${formatPct(newRate)} / ${formatYears(amortYears)}`,
        result: formatUsd(newDs)
      },
      {
        label: "New DSCR",
        expression: `${formatUsd(noi2)} / ${formatUsd(newDs)}`,
        result: formatMultiple(newDscr)
      }
    ],
    answerDisplay: `${formatMultiple(newDscr)} (\u0394 ${delta >= 0 ? "+" : ""}${delta.toFixed(2)}x)`
  };
}
