function buildSolution13(noi2, loan, rate, years, threshold) {
  const ds = annualDebtService(loan, rate, years);
  const ratio = dscr(noi2, ds);
  const passes = ratio >= threshold;
  const headroom = ds * (ratio / threshold - 1);
  return {
    formula: "DSCR = NOI / DS;  pass when DSCR \u2265 threshold",
    steps: [
      {
        label: "Annual debt service",
        expression: `${formatUsd(loan)} @ ${formatPct(rate)} / ${formatYears(years)}`,
        result: formatUsd(ds)
      },
      {
        label: "DSCR",
        expression: `${formatUsd(noi2)} / ${formatUsd(ds)}`,
        result: formatMultiple(ratio)
      },
      {
        label: passes ? "Headroom (NOI cushion)" : "Shortfall",
        expression: passes ? `(${formatMultiple(ratio)} \u2212 ${formatMultiple(threshold)}) \xD7 DS` : `(${formatMultiple(threshold)} \u2212 ${formatMultiple(ratio)}) \xD7 DS`,
        result: formatUsd(Math.abs(headroom))
      }
    ],
    answerDisplay: passes ? `Pass \u2014 ${formatUsd(headroom)} headroom` : `Fail \u2014 ${formatUsd(Math.abs(headroom))} short`
  };
}
