// src/math/returns.ts
function equityMultiple(equityIn, equityOut) {
  return equityOut / equityIn;
}
function irrSingle(equityIn, equityOut, years) {
  return Math.pow(equityOut / equityIn, 1 / years) - 1;
}
function requiredMultiple(irr, years) {
  return Math.pow(1 + irr, years);
}
function irrMulti(cashflows, guess = 0.1) {
  if (cashflows.length < 2) return NaN;
  let hasPos = false;
  let hasNeg = false;
  for (const cf of cashflows) {
    if (cf > 0) hasPos = true;
    if (cf < 0) hasNeg = true;
  }
  if (!hasPos || !hasNeg) return NaN;
  const f = (rate) => {
    let v = 0;
    for (let t = 0; t < cashflows.length; t++) {
      v += cashflows[t] / Math.pow(1 + rate, t);
    }
    return v;
  };
  const fPrime = (rate) => {
    let v = 0;
    for (let t = 1; t < cashflows.length; t++) {
      v -= t * cashflows[t] / Math.pow(1 + rate, t + 1);
    }
    return v;
  };
  let r = guess;
  for (let i = 0; i < 50; i++) {
    const fr = f(r);
    if (Math.abs(fr) < 1e-9) return r;
    const fpr = fPrime(r);
    if (fpr === 0) break;
    const next = r - fr / fpr;
    if (!Number.isFinite(next)) break;
    if (Math.abs(next - r) < 1e-10) return next;
    r = Math.max(-0.999, next);
  }
  let lo = -0.99;
  let hi = 10;
  let flo = f(lo);
  if (flo * f(hi) > 0) return NaN;
  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    const fm = f(mid);
    if (Math.abs(fm) < 1e-9) return mid;
    if (flo * fm < 0) {
      hi = mid;
    } else {
      lo = mid;
      flo = fm;
    }
  }
  return (lo + hi) / 2;
}

