// src/math/lease.ts
function netEffectiveRent(params) {
  const months = params.leaseTermYears * 12;
  const grossTotal = params.grossRentPerSf * params.leaseTermYears;
  const freeRent = params.grossRentPerSf / 12 * params.freeMonths;
  const netTotalPerSf = grossTotal - params.tiPerSf - freeRent;
  return netTotalPerSf / months * 12;
}
function effectiveRentCostPerSf(params) {
  const total = params.rentPerSf * params.leaseTermYears - params.tiPerSf;
  return total / params.leaseTermYears;
}
function tiVsRentDelta(params) {
  const a = effectiveRentCostPerSf({
    rentPerSf: params.rentA,
    tiPerSf: params.tiA,
    leaseTermYears: params.leaseTermYears
  });
  const b = effectiveRentCostPerSf({
    rentPerSf: params.rentB,
    tiPerSf: params.tiB,
    leaseTermYears: params.leaseTermYears
  });
  return a - b;
}
function requiredRentPremiumPerSf(params) {
  return params.tiPerSf / params.paybackYears;
}
function rentRollNoiChange(params) {
  return (params.newRentPerSf - params.oldRentPerSf) * params.subjectSf * (1 - params.vacancy);
}
function rentRollValueChange(params) {
  return rentRollNoiChange(params) / params.capRate;
}
function taxReassessmentValueImpact(params) {
  const newTax = params.purchasePrice * params.newTaxRate;
  const taxDelta = newTax - params.oldAnnualTax;
  return -taxDelta / params.capRate;
}

// src/quiz/templates/netEffectiveRent.ts
function buildSolution29(params) {
  const months = params.years * 12;
  const freePerSf = params.grossRent / 12 * params.freeMonths;
  const ner = netEffectiveRent({
    grossRentPerSf: params.grossRent,
    leaseTermYears: params.years,
    tiPerSf: params.tiPerSf,
    freeMonths: params.freeMonths
  });
  return {
    formula: "NER = (Gross \xD7 Term \u2212 TI \u2212 Free Rent) / Term",
    steps: [
      {
        label: "Gross over term",
        expression: `${formatUsdPerSf(params.grossRent)} \xD7 ${formatYears(params.years)}`,
        result: formatUsdPerSf(params.grossRent * params.years)
      },
      {
        label: "Free rent /SF",
        expression: `${formatUsdPerSf(params.grossRent / 12)} \xD7 ${params.freeMonths} months`,
        result: formatUsdPerSf(freePerSf)
      },
      {
        label: "NER",
        expression: `(${formatUsdPerSf(params.grossRent * params.years)} \u2212 ${formatUsdPerSf(params.tiPerSf)} \u2212 ${formatUsdPerSf(freePerSf)}) / ${months}mo \xD7 12`,
        result: formatUsdPerSf(ner)
      }
    ],
    answerDisplay: formatUsdPerSf(ner)
  };
}
