// src/quiz/templates/irrAfterPromote.ts
function lpIrrAfterPromote(irrBeforePromote, promotePct, years) {
  const dealEm = Math.pow(1 + irrBeforePromote, years);
  const lpEm = 1 + (1 - promotePct) * (dealEm - 1);
  return Math.pow(lpEm, 1 / years) - 1;
}
var PROMOTE_PCTS = [0.1, 0.15, 0.2, 0.25, 0.3];
var IRR_PRE = [0.12, 0.14, 0.16, 0.18, 0.2, 0.22, 0.25];
function buildSolution46(irrBefore, promote, years, expected) {
  const dealEm = Math.pow(1 + irrBefore, years);
  const lpEm = 1 + (1 - promote) * (dealEm - 1);
  return {
    formula: "LP EM = 1 + (1 \u2212 promote%) \xD7 (deal EM \u2212 1); LP IRR = LP EM^(1/n) \u2212 1",
    steps: [
      {
        label: "Deal EM",
        expression: `(1 + ${formatPct(irrBefore, 0)})^${years}`,
        result: dealEm.toFixed(3)
      },
      {
        label: "LP EM after promote",
        expression: `1 + (1 \u2212 ${formatPct(promote, 0)}) \xD7 (${dealEm.toFixed(3)} \u2212 1)`,
        result: lpEm.toFixed(3)
      },
      {
        label: "LP IRR",
        expression: `${lpEm.toFixed(3)}^(1/${years}) \u2212 1`,
        result: formatPct(expected, 1)
      }
    ],
    answerDisplay: formatPct(expected, 1)
  };
}
