function rentWeightedWalt(leases) {
  const totalRent = leases.reduce((s, l) => s + l.rent, 0);
  if (totalRent === 0) return 0;
  const weighted = leases.reduce((s, l) => s + l.rent * l.remainingTerm, 0);
  return weighted / totalRent;
}
