// src/quiz/templates/refiStressTest.ts
function buildSolution64(loan, noi2, ltv, capStress) {
  const newValue = noi2 / capStress;
  const maxLoan = ltv * newValue;
  return {
    formula: "cap_stress = LTV \xD7 NOI / existing_loan",
    steps: [
      {
        label: "Refi constraint",
        expression: `${formatPct(ltv, 0)} \xD7 NOI \xF7 cap_stress = existing loan`,
        result: "solve for cap_stress"
      },
      {
        label: "Rearrange",
        expression: `${formatPct(ltv, 0)} \xD7 ${formatUsd(noi2)} / ${formatUsd(loan)}`,
        result: formatPct(capStress, 2)
      },
      {
        label: "Sanity check",
        expression: `value @ stress = NOI / ${formatPct(capStress, 2)}`,
        result: `${formatUsd(newValue)}; max loan @ LTV = ${formatUsd(maxLoan)}`
      }
    ],
    answerDisplay: formatPct(capStress, 2)
  };
}
